import{_ as t,C as r,o as i,c as n,j as a,a as s,G as c,a2 as l}from"./chunks/framework.BgSoyxN5.js";const w=JSON.parse('{"title":"TickerForge Demo | How the Research Software Works","description":"See how TickerForge stock checks, portfolio diagnostics, market regime context, and monitoring workflows work before using paid features.","frontmatter":{"title":"TickerForge Demo | How the Research Software Works","description":"See how TickerForge stock checks, portfolio diagnostics, market regime context, and monitoring workflows work before using paid features."},"headers":[],"relativePath":"demo.md","filePath":"demo.md","lastUpdated":1783323835000}'),d={name:"demo.md"};function h(p,e,m,u,f,g){const o=r("TickerForgeComplianceDisclaimer");return i(),n("div",null,[e[0]||(e[0]=a("h1",{id:"tickerforge-demo",tabindex:"-1"},[s("TickerForge Demo "),a("a",{class:"header-anchor",href:"#tickerforge-demo","aria-label":'Permalink to "TickerForge Demo"'},"​")],-1)),e[1]||(e[1]=a("p",null,"TickerForge is a software platform for portfolio analytics, watchlist monitoring, market research workflows, and educational diagnostics. This demo explains the product path without requiring a reviewer or new user to log in.",-1)),c(o),e[2]||(e[2]=l('<h2 id="_1-open-a-widget" tabindex="-1">1. Open a Widget <a class="header-anchor" href="#_1-open-a-widget" aria-label="Permalink to &quot;1. Open a Widget&quot;">​</a></h2><p>Start from one of the browser workflows:</p><ul><li><a href="/stock-widget">Stock Check Widget</a></li><li><a href="/import-portfolio">Import Portfolio</a></li><li><a href="/portfolio-diagnostics">Portfolio Diagnostics Demo</a></li><li><a href="/market-widget">Market Regime Widget</a></li><li><a href="/smart-money-radar">Smart Money Radar</a></li></ul><p>These widgets are software interfaces for research and monitoring. They do not execute trades.</p><h2 id="_2-run-a-stock-check-example" tabindex="-1">2. Run a Stock Check Example <a class="header-anchor" href="#_2-run-a-stock-check-example" aria-label="Permalink to &quot;2. Run a Stock Check Example&quot;">​</a></h2><p>Open the <a href="/stock-widget">Stock Check Widget</a> and enter <code>MSFT</code> or <code>show Microsoft</code>.</p><p>TickerForge returns a structured research output: business quality, financial context, valuation context, risk, technical setup, reported fund activity, insider activity, and a research next step. The output is not a recommendation to buy or sell.</p><h2 id="_3-run-a-portfolio-health-example" tabindex="-1">3. Run a Portfolio Health Example <a class="header-anchor" href="#_3-run-a-portfolio-health-example" aria-label="Permalink to &quot;3. Run a Portfolio Health Example&quot;">​</a></h2><p>Open <a href="/portfolio-diagnostics">Portfolio Diagnostics Demo</a> to inspect public model portfolios, or use <a href="/import-portfolio">Import Portfolio</a> to enter sample holdings and cash.</p><p>TickerForge generates software diagnostics such as snapshot, health score, sector concentration, beta exposure, and stress-test estimates. No broker account connection or trade execution is required.</p><h2 id="_4-review-market-regime-context" tabindex="-1">4. Review Market Regime Context <a class="header-anchor" href="#_4-review-market-regime-context" aria-label="Permalink to &quot;4. Review Market Regime Context&quot;">​</a></h2><p>Open the <a href="/market-widget">Market Regime Widget</a> to compare the latest daily and weekly market context used by TickerForge. This helps users understand market stress, regime, and sector rotation before doing additional research.</p><h2 id="_5-request-monitoring" tabindex="-1">5. Request Monitoring <a class="header-anchor" href="#_5-request-monitoring" aria-label="Permalink to &quot;5. Request Monitoring&quot;">​</a></h2><p>After a widget result, users can request recurring monitoring by email or continue in Telegram. Monitoring can include research alerts when selected watchlist, portfolio, market-risk, or indicator conditions change.</p><h2 id="_6-paid-plans" tabindex="-1">6. Paid Plans <a class="header-anchor" href="#_6-paid-plans" aria-label="Permalink to &quot;6. Paid Plans&quot;">​</a></h2><p>Paid plans unlock software features such as expanded monitoring limits, saved watchlists, recurring portfolio diagnostics, email/Telegram research notifications, exports, and advanced analytics views. Plan details are shown on the <a href="/pricing">Pricing page</a>.</p><p>Paid features are software access features, not financial advice, trade execution, or guaranteed investment outcomes.</p>',17))])}const x=t(d,[["render",h]]);export{w as __pageData,x as default};
